mapper.select:
        SELECT
        IFNULL(SUM(money), 0)
        FROM
        user_money_details
        WHERE user_id = #{userId}
        
            AND user_level =#{level}

SELECT u.user_id as userId, u.avatar, u.user_name as userName, IFNULL(SUM(d.money),0) as money FROM user_money_details d LEFT JOIN tb_user u on u.user_id = d.user_id WHERE d.relation_id = #{userId} AND d.classify = 3
AND d.user_level = #{type}
GROUP BY d.relation_id,u.user_id, u.avatar, u.user_name ORDER BY money DESC
